// Linear Congruential Generator to produce uniform random numbers in (0, 1)
    auto lcg = [&]() {
        seed = (a * seed + c) % m;
        return static_cast<double>(seed) / m;
    };

    // Generate two uniform random numbers
    double u1 = lcg();
    double u2 = lcg();

    // Avoid log(0) by ensuring u1 is not zero
    while (u1 == 0.0) {
        u1 = lcg();
    }

    // Box-Muller transform
    double z0 = std::sqrt(-2.0 * std::log(u1)) * std::cos(2.0 * std::numbers::pi * u2);
    // double z1 = std::sqrt(-2.0 * std::log(u1)) * std::sin(2.0 * std::numbers::pi * u2); // Second random number (unused)

    // Scale and shift to desired mean and standard deviation
    return mean + sigma * z0;

